#import <Foundation/Foundation.h>
#import <AppKit/AppKit.h>

int main() {
    // Find the iOS Simulator
    NSArray *runningApps = [[NSWorkspace sharedWorkspace] runningApplications];
    NSRunningApplication *simApp = nil;

    for (NSRunningApplication *app in runningApps) {
        if ([app.localizedName containsString:@"Simulator"] || 
            [app.bundleIdentifier isEqualToString:@"com.apple.iphonesimulator"]) {
            simApp = app;
            break;
        }
    }

    if (!simApp) {
        NSLog(@"Simulator not found");
        return 1;
    }

    NSLog(@"Found simulator: %@", simApp.localizedName);

    // Try to use the accessibility API to find and click the "Open" button
    AXUIElementRef appElement = AXUIElementCreateApplication(simApp.processIdentifier);

    // Get all windows
    CFArrayRef windows;
    AXUIElementCopyAttributeValue(appElement, kAXWindowsAttribute, (CFTypeRef *)&windows);

    if (windows && CFArrayGetCount(windows) > 0) {
        AXUIElementRef window = (AXUIElementRef)CFArrayGetValueAtIndex(windows, 0);

        // Search for buttons
        CFArrayRef buttons;
        if (AXUIElementCopyAttributeValue(window, kAXButtonsAttribute, (CFTypeRef *)&buttons) == kAXErrorSuccess) {
            NSLog(@"Found buttons");
            CFRelease(buttons);
        }

        CFRelease(windows);
    }

    CFRelease(appElement);

    return 0;
}
EOF

